// Package dashboardbundle embeds the prebuilt admin dashboard (the original
// packages/admin/dashboard React app built with @medusajs/admin-bundler) so
// the Go server serves the admin without Node.
//
// app/ is generated by scripts/build-admin-bundle.sh: a "runtime" template
// whose base path and compiled-in options are filled in when it is served
// (see packages/admin/admin-bundler/src/commands/serve.go). build-admin.mjs is
// the Node build script, also used by `medusa build` for projects with admin
// extensions.
package dashboardbundle

import (
	"embed"
	"io/fs"
)

//go:embed all:app
var files embed.FS

// BuildScript is build-admin.mjs.
//
//go:embed build-admin.mjs
var BuildScript []byte

// App returns the dashboard files (index.html, assets/...).
func App() fs.FS {
	sub, err := fs.Sub(files, "app")
	if err != nil {
		panic(err)
	}
	return sub
}
